import{_ as a,o as t,c as o,a5 as r}from"./chunks/framework.BwlBv862.js";const h=JSON.parse('{"title":"実用的な自動化レシピを応用する","description":"","frontmatter":{"title":"実用的な自動化レシピを応用する","docId":"user.automations.recipes","translationKey":"user.automations.recipes","locale":"ja","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"43a103ef68e43d691eec2214ffefb5e2e0e6b663afa9f4e63b5dac0ccec162ea","translationRevision":"7cf62155024ff018d9d7546a36872ecab40632a41167439bbaaeb853272f69e5","order":30},"headers":[],"relativePath":"ja/user/automations/recipes.md","filePath":"ja/user/automations/recipes.md","lastUpdated":1794611623000}'),c={name:"ja/user/automations/recipes.md"};function i(d,e,s,n,l,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="adapt-practical-automation-recipes" tabindex="-1">実用的な自動化レシピを応用する <a class="header-anchor" href="#adapt-practical-automation-recipes" aria-label="Permalink to &quot;実用的な自動化レシピを応用する {#adapt-practical-automation-recipes}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>正常に動く<a href="./first-rule.html">ログ記録ルール</a> を、条件を絞った反応へ発展させます。アクティブなプロファイルと、実際に確認したイベントのフィールドが必要です。まず <code>core.log</code> を使い、一致条件と頻度を確認してから別の処理に置き換えます。</p><h2 id="match-a-chat-command" tabindex="-1">チャットコマンドに一致させる <a class="header-anchor" href="#match-a-chat-command" aria-label="Permalink to &quot;チャットコマンドに一致させる {#match-a-chat-command}&quot;">​</a></h2><p><code>tiktok.chat</code> イベントを作り、<code>event.data.comment</code> が <code>!こんにちは</code> に等しい (<code>eq</code>) 条件を設定します。ログは次のようにします。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>こんにちは {{ event.user.uniqueId }}</span></span></code></pre></div><p>ユーザー別クールダウンを <code>30</code> 秒にすると、1人が連続して実行することを防ぎ、別の視聴者には独立した機会を残せます。コマンドには完全一致が便利です。「含む」では前後に別の文言があるメッセージも一致するため、意図に合わせて選んでください。</p><h2 id="record-a-qualifying-gift" tabindex="-1">条件を満たすギフトを記録する <a class="header-anchor" href="#record-a-qualifying-gift" aria-label="Permalink to &quot;条件を満たすギフトを記録する {#record-a-qualifying-gift}&quot;">​</a></h2><p><code>tiktok.gift</code> イベントを作り、<code>event.data.diamondCount</code> が <code>10</code> 以上 (<code>gte</code>) の条件を設定します。ログは次のとおりです。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{{ event.user.uniqueId }} からのギフト: {{ event.data.giftName }}</span></span></code></pre></div><p>最初に実際のギフト詳細を確認します。ダイヤモンドの価値、連続回数、完了フラグは別々のフィールドです。完了時だけ反応させるなら、受信ペイロードに <code>event.data.repeatEnd</code> があることを確認し、真偽値 true の条件を使います。名前のフィルターだけで、コンボ完了ごとに1回実行されるとは判断できません。</p><h2 id="bound-a-shared-reaction" tabindex="-1">共有する反応の頻度を制限する <a class="header-anchor" href="#bound-a-shared-reaction" aria-label="Permalink to &quot;共有する反応の頻度を制限する {#bound-a-shared-reaction}&quot;">​</a></h2><p><code>tiktok.follow</code> イベントに全体のクールダウン <code>10</code> 秒を設定し、短いログアクションを関連付けます。その間に2人がフォローすると、後の反応が抑制されることがあります。視聴者ごとに機会が必要ならユーザー別の範囲を使います。</p><p>複数のアクションでは一覧を順に並べ、全手順が必要なら全アクション実行モードを維持します。ランダムモードは1つを選ぶ方式で、全手順をランダム順に実行する方式ではありません。後続手順を待たせる場合だけ <code>core.delay</code> を追加します。</p><h2 id="expected-result-and-status" tabindex="-1">期待される結果と提供状況 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;期待される結果と提供状況 {#expected-result-and-status}&quot;">​</a></h2><p>これらのトリガー、フィールドフィルター、クールダウンはローカルエンジンで利用できます。有効状態とクールダウンの制約の下で、受け付けた一致イベントに対応する実行結果が得られます。プロバイダー固有の動作は実際の LIVE で確認する必要があります。</p><h2 id="recovery" tabindex="-1">問題が起きたとき <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;問題が起きたとき {#recovery}&quot;">​</a></h2><p>失敗したらログ1つに戻し、ペイロードを確認して一時的に条件を簡単にします。調査中も混雑した配信の制限を解除しないでください。音声、ポイント、HTTP、プラグインのテストでは実際の処理が動きます。追加前に<a href="./../plugins/audio.html">音声設定</a>、<a href="./variables.html">変数</a>、<a href="./../preferences/troubleshooting.html">実行時の診断</a> を確認します。</p>',18)])])}const m=a(c,[["render",i]]);export{h as __pageData,m as default};
